function Modal({title,kicker,children,close}:{title:string;kicker?:string;children:ReactNode;close:()=>void}){const root=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';const el=root.current;el?.focus();const handle=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'){const list=el?.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,textarea,a[href]');if(!list?.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===el)){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',handle);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',handle);previous?.focus()}},[]);return <div className="overlay" onClick={e=>{if(e.target===e.currentTarget)close()}}><div className="modal" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={root}><button className="icon close" aria-label="Close dialog" onClick={close}><X size={20}/></button>{kicker&&<div className="eyebrow">{kicker}</div>}<h2>{title}</h2>{children}</div></div>}
